const COUNTRY_SLUGS = ['canada', 'usa', 'uk', 'germany', 'uae', 'australia'] as const;
const COUNTRY_SUFFIX_RE = /-(australia|canada|usa|uk|germany|uae)$/i;

/** Derive a clean service name when serviceType was corrupted during bulk generation. */
export function deriveServiceName(service: ServiceData): string {
  const st = service.serviceType?.trim() ?? '';
  const countrySuffixOnly = /^(Australia|Canada|USA|UK|Germany|UAE)$/i;
  const truncatedPattern = /\s+(Australia|Canada|USA|UK|Germany|UAE|Uae|Usa|Uk)$/i;

  const isCorrupted =
    !st ||
    countrySuffixOnly.test(st) ||
    (truncatedPattern.test(st) && st.split(/\s+/).length <= 3);

  if (!isCorrupted) return st;

  const titleMatch = service.title.match(/^(.+?)\s+for\s+/i);
  if (titleMatch) return titleMatch[1].trim();

  const base = service.slug.replace(COUNTRY_SUFFIX_RE, '');
  return base
    .split('-')
    .map((part) => {
      const lower = part.toLowerCase();
      if (lower === 'ai') return 'AI';
      if (lower === 'uiux') return 'UI/UX';
      if (lower === 'ci' || lower === 'cd') return part.toUpperCase();
      if (lower === 'cd' && base.includes('ci-cd')) return 'CD';
      return part.charAt(0).toUpperCase() + part.slice(1);
    })
    .join(' ')
    .replace(/\bCi\b/g, 'CI')
    .replace(/\bCd\b/g, 'CD');
}

let cachedCountryServicePages: CountryServicePageContent[] | null = null;
let countryServicePageByKey: Map<string, CountryServicePageContent> | null = null;

// Generate all country service pages (every service in servicesByCountry for each location)
export function getAllCountryServicePages(): CountryServicePageContent[] {
  if (cachedCountryServicePages) {
    return cachedCountryServicePages;
  }

  const allPages: CountryServicePageContent[] = [];

  COUNTRY_SLUGS.forEach((country) => {
    const countryData = getCountryData(country);
    if (!countryData) return;

    const services = servicesByCountry[countryData.name];
    if (!services?.length) return;

    services.forEach((service) => {
      const baseSlug = service.slug.replace(COUNTRY_SUFFIX_RE, '');
      const globalPage = getServicePage(baseSlug);
      const serviceName = deriveServiceName(service);
      const rawSections = service.sections?.length ? service.sections : globalPage?.sections ?? [];

      allPages.push({
        ...service,
        categorySlug: country,
        countryName: countryData.name,
        countryCode: getCountryCode(country),
        serviceName,
        slug: service.slug,
        title: service.title,
        // Open item #11 — "{Service} in {Country}" (brand appended once by buildPageMetadata)
        metaTitle: `${serviceName} in ${countryData.name}`,
        metaDescription: service.metaDescription,
        lead: globalPage?.lead ?? service.metaDescription,
        highlights: service.highlights?.length ? service.highlights : globalPage?.highlights,
        // Open item #14 — the shared "Why {Country} Companies Choose ClickMasters" H2 appeared on
        // all 107 pages per country; name the service so each page's heading is unique.
        sections: rawSections.map((section) =>
          /^Why .+ Companies Choose ClickMasters$/i.test(section.heading ?? '')
            ? { ...section, heading: `Why ${countryData.name} Companies Choose ClickMasters for ${serviceName}` }
            : section
        ),
        servicesCards: globalPage?.servicesCards?.map((card) => ({
          title: card.title,
          description: card.description,
          icon: '⚡',
          features: [],
        })),
        differentiators: globalPage?.differentiators?.map((d) => ({
          title: d.feature,
          description: d.description,
          icon: '✓',
        })),
        processPhases: service.processPhases ?? globalPage?.processPhases,
        industryUseCases: globalPage?.industryUseCases?.map((i) => ({
          industry: i.name,
          description: i.description,
          useCase: i.description,
        })),
        tables: globalPage?.tables,
        countryPricingTiers: service.countryPricingTiers ?? globalPage?.pricingTiers ?? [],
        faqs: service.faqs?.length ? service.faqs : globalPage?.faqs ?? [],
      });
    });
  });

  cachedCountryServicePages = allPages;
  countryServicePageByKey = new Map(
    allPages.map((page) => [`${page.categorySlug}/${page.slug}`, page])
  );

  return allPages;
}

/** Map display names from country.ts to actual slugs in servicesByCountry. */
export function buildCountryServiceSlugMap(
  countryName: string,
  location: string
): Record<string, string> {
  const services = servicesByCountry[countryName] ?? [];
  const map: Record<string, string> = {};

  for (const service of services) {
    map[deriveServiceName(service)] = service.slug;
    if (service.serviceType) map[service.serviceType] = service.slug;
  }

  const countryData = getCountryData(location);
  if (!countryData) return map;

  for (const category of countryData.servicesByCategory) {
    for (const name of category.services) {
      const expected = `${slugify(name)}-${location.toLowerCase()}`;
      const exact = services.find((s) => s.slug === expected);
      if (exact) {
        map[name] = exact.slug;
        continue;
      }
      const prefix = `${slugify(name)}-`;
      const fuzzy = services.find((s) => s.slug.startsWith(prefix));
      if (fuzzy) {
        map[name] = fuzzy.slug;
      }
    }
  }

  // Known display-name → closest available page slugs (no dedicated country page exists)
  const fallbackAliases: Record<string, string> = {
    'Native App Development': 'mobile-app-development',
    'Cross Platform App Development': 'cross-platform-app-development',
    'Wireframing Prototyping': 'wireframing-prototyping',
    'API Development Integration': 'api-development-integration',
    'SQL NoSQL Solutions': 'sql-nosql-solutions',
  };

  for (const [displayName, slugBase] of Object.entries(fallbackAliases)) {
    if (map[displayName]) continue;
    const fallback = services.find((s) => s.slug === `${slugBase}-${location.toLowerCase()}`);
    if (fallback) map[displayName] = fallback.slug;
  }

  return map;
}

// Helper function to extract base service slug without country suffix
function getBaseServiceSlug(fullSlug: string, country: string): string {
  const countrySuffix = `-${country.toLowerCase()}`;
  if (fullSlug.endsWith(countrySuffix)) {
    return fullSlug.slice(0, -countrySuffix.length);
  }
  return fullSlug;
}

// Helper function to get country code
function getCountryCode(country: string): string {
  const codes: Record<string, string> = {
    canada: 'CA',
    usa: 'US',
    uk: 'GB',
    germany: 'DE',
    uae: 'AE',
    australia: 'AU'
  };
  return codes[country] || 'US';
}

// Get specific country service page
export function getCountryServicePage(service: string, country: string): CountryServicePageContent | undefined {
  getAllCountryServicePages();
  return countryServicePageByKey?.get(`${country}/${service}`);
}

// Get technologies for specific service and country
export function getCountryServiceTechnologies(service: string, country: string): string[] {
  if (!getCountryData(country)) return [];

  const baseTechnologies = ['React / Next.js', 'Node.js', 'TypeScript', 'AWS', 'Docker'];
  const baseSlug = service.replace(COUNTRY_SUFFIX_RE, '');

  const serviceTechMap: Record<string, string[]> = {
    'ai-agents-development': ['Python', 'TensorFlow', 'PyTorch', 'LangChain', 'OpenAI APIs'],
    'ai-automation-systems': ['Python', 'TensorFlow', 'Apache Airflow', 'Docker', 'Kubernetes'],
    'mobile-app-development': ['React Native', 'Flutter', 'Swift', 'Kotlin', 'TypeScript'],
    'web-development': ['React', 'Next.js', 'Node.js', 'TypeScript', 'PostgreSQL', 'MongoDB'],
    'video-analytics': ['OpenCV', 'Python', 'TensorFlow', 'AWS Rekognition', 'Edge AI'],
  };

  return serviceTechMap[baseSlug] || baseTechnologies;
}

export const getAllServices = (): ServiceData[] => {
  return Object.values(servicesByCountry).flat();
};

export const getServicesByCountry = (country: string): ServiceData[] => {
  return servicesByCountry[country] || [];
};

export const getCountries = (): string[] => {
  return Object.keys(servicesByCountry);
};

export const getServiceTypes = (): string[] => {
  const types = new Set<string>();
  getAllServices().forEach(service => types.add(service.serviceType));
  return Array.from(types).sort();
};
